// For path existence, check if path exists (file or dir)
fn path_exists(p: &str) -> bool {
    Path::new(p).exists()
}

fn is_inside_vroot(path: &str, vroot: &str) -> bool {
    // canonicalize both if possible, else use string prefix
    // Use absolute paths: if path is relative, join with cwd
    let cwd = env::current_dir().unwrap_or_else(|_| PathBuf::from("."));
    let abs_path = if Path::new(path).is_absolute() {
        PathBuf::from(path)
    } else {
        cwd.join(path)
    };
    let abs_vroot = if Path::new(vroot).is_absolute() {
        PathBuf::from(vroot)
    } else {
        cwd.join(vroot)
    };
    // Try canonicalize, but if fails due to not exists? But we already checked exists, so canonicalize should succeed for existing paths
    let canon_path = fs::canonicalize(&abs_path).unwrap_or(abs_path);
    let canon_vroot = fs::canonicalize(&abs_vroot).unwrap_or(abs_vroot);
    let canon_path_str = canon_path.to_string_lossy();
    let canon_vroot_str = canon_vroot.to_string_lossy();
    // Check if canon_path == canon_vroot or starts with canon_vroot + "/"
    if canon_path_str == canon_vroot_str {
        return true;
    }
    let vroot_with_slash = format!("{}/", canon_vroot_str.trim_end_matches('/'));
    canon_path_str.starts_with(&vroot_with_slash)
}

// Placeholder parsing
#[derive(Debug, Clone, PartialEq)]
enum Placeholder {
    S(usize), // column
    Q(usize),
    StarS(usize),
    StarQ(usize),
}

fn parse_template(template: &str) -> Result<(Vec<Placeholder>, String), String> {
    // Returns placeholders and error if invalid
    let mut placeholders = Vec::new();
    let chars: Vec<char> = template.chars().collect();
    let mut i = 0;
    while i < chars.len() {
        if chars[i] == '%' {
            if i + 1 >= chars.len() {
                return Err("error: xplr -m: template ended with incomplete placeholder\n".to_string());
            }
            let col = i + 1; // 1-indexed
            let nxt = chars[i+1];
            if nxt == '%' {
                // escaped, skip
                i += 2;
                continue;
            } else if nxt == 's' {
                placeholders.push(Placeholder::S(col));
                i += 2;
            } else if nxt == 'q' {
                placeholders.push(Placeholder::Q(col));
                i += 2;
            } else if nxt == '*' {
                if i + 2 >= chars.len() {
                    return Err("error: xplr -m: template ended with incomplete placeholder\n".to_string());
                }
                let nxt2 = chars[i+2];
                if nxt2 == 's' {
                    placeholders.push(Placeholder::StarS(col));
                    i += 3;
                } else if nxt2 == 'q' {
                    placeholders.push(Placeholder::StarQ(col));
                    i += 3;
                } else {
                    // invalid like %*x
                    let ph = format!("%*{}", nxt2);
                    return Err(format!("error: xplr -m: invalid placeholder '{}' at column {}, use one of '%s' or '%q', or escape it using '%%'\n", ph, col));
                }
            } else {
                let ph = format!("%{}", nxt);
                return Err(format!("error: xplr -m: invalid placeholder '{}' at column {}, use one of '%s' or '%q', or escape it using '%%'\n", ph, col));
            }
        } else {
            i += 1;
        }
    }
    Ok((placeholders, template.to_string()))
}

fn substitute_template(template: &str, placeholders: &[Placeholder], values: &[String]) -> Result<String, String> {
    // Build result string by replacing placeholders in order
    // For star placeholders, they consume all remaining values.
    // For normal, one value each.
    // Need to handle %% -> %
    let mut result = String::new();
    let chars: Vec<char> = template.chars().collect();
    let mut i = 0;
    let mut val_idx = 0;
    let mut ph_idx = 0;
    while i < chars.len() {
        if chars[i] == '%' {
            if i+1 < chars.len() && chars[i+1] == '%' {
                result.push('%');
                i += 2;
                continue;
            }
            // This should be a placeholder, we need to find which one corresponds to this position
            // We have placeholders list in order; the current placeholder to process is placeholders[ph_idx]
            if ph_idx >= placeholders.len() {
                // shouldn't happen
                result.push(chars[i]);
                i+=1;
                continue;
            }
            let ph = &placeholders[ph_idx];
            ph_idx += 1;
            match ph {
                Placeholder::S(col) => {
                    if val_idx >= values.len() {
                        return Err(format!("error: xplr -m: placeholder missing value at column {}\n", col));
                    }
                    result.push_str(&values[val_idx]);
                    val_idx += 1;
                    i += 2;
                },
                Placeholder::Q(col) => {
                    if val_idx >= values.len() {
                        return Err(format!("error: xplr -m: placeholder missing value at column {}\n", col));
                    }
                    let v = &values[val_idx];
                    // Use JSON string quoting
                    let quoted = serde_json::to_string(v).unwrap();
                    result.push_str(&quoted);
                    val_idx += 1;
                    i += 2;
                },
                Placeholder::StarS(col) => {
                    // consume all remaining
                    let remaining = &values[val_idx..];
                    let joined = remaining.join(",");
                    result.push_str(&joined);
                    val_idx = values.len();
                    i += 3;
                    // If there are more placeholders after star, they will be processed next iteration and will fail missing value
                },
                Placeholder::StarQ(col) => {
                    let remaining = &values[val_idx..];
                    let quoted_vals: Vec<String> = remaining.iter().map(|v| serde_json::to_string(v).unwrap()).collect();
                    let joined = quoted_vals.join(",");
                    result.push_str(&joined);
                    val_idx = values.len();
                    i += 3;
                },
            }
        } else {
            result.push(chars[i]);
            i+=1;
        }
    }
    if val_idx < values.len() {
        return Err("error: xplr -m: too many positional values, not enough positional placeholders\n".to_string());
    }
    if ph_idx < placeholders.len() {
        // This can happen if star consumed all and then later placeholder missing, we already returned missing above?
        // But if placeholders left are star that consumed 0 values, and there are still placeholders left? Actually we handled missing above for normal placeholders after star.
        // For star case where star at end and zero values, we already handled and ph_idx advanced, val_idx == len, no missing.
        // So this check is for leftover placeholders not processed due to early return? Not needed.
    }
    Ok(result)
}

