fn validate_message(yaml_str: &str) -> Result<serde_json::Value, String> {
    // First try to parse yaml
    let yaml_val: serde_yaml::Value = match serde_yaml::from_str(yaml_str) {
        Ok(v) => v,
        Err(e) => {
            return Err(format!("error: xplr -m: yaml: {}\n", e));
        }
    };
    // Then try to deserialize to MsgEnum to validate
    // We need to deserialize from yaml_val via serde_yaml
    let de = serde_yaml::from_str::<MsgEnum>(yaml_str);
    match de {
        Ok(msg) => {
            // Serialize to json value
            let json_val = serde_json::to_value(&msg).unwrap();
            Ok(json_val)
        },
        Err(e) => {
            // e is serde_yaml error, need to format as "error: {msg} at line 1 column X"
            // The error string already contains "unknown variant..." or "invalid type..."
            // It may already contain at line ...?
            // We need to ensure prefix is "error: "
            let err_str = e.to_string();
            // It already contains "at line 1 column X" ?
            // We'll prefix with "error: "
            if err_str.starts_with("unknown variant") || err_str.starts_with("invalid type") || err_str.starts_with("missing field") {
                return Err(format!("error: {} at line 1 column 1\n", err_str));
            } else {
                // Need to extract line/column from err?
                // For now, return with prefix
                return Err(format!("error: {}\n", err_str));
            }
        }
    }
}

