    let canon_path = fs::canonicalize(&abs_path).unwrap_or(abs_path);
    let canon_vroot = fs::canonicalize(&abs_vroot).unwrap_or(abs_vroot);
    let cp = canon_path.to_string_lossy();
    let cv = canon_vroot.to_string_lossy();
    if cp == cv { return true; }
    let vslash = format!("{}/", cv.trim_end_matches('/'));
