#[derive(Debug, Clone, PartialEq)]
enum Placeholder { S(usize), Q(usize), StarS(usize), StarQ(usize) }

fn parse_template(template: &str) -> Result<Vec<Placeholder>, String> {
    let chars: Vec<char> = template.chars().collect();
    let mut placeholders = Vec::new();
    let mut i=0;
    while i<chars.len() {
        if chars[i]=='%' {
            if i+1>=chars.len() { return Err("error: xplr -m: template ended with incomplete placeholder\n".to_string()); }
            let col=i+1;
            let nxt=chars[i+1];
            if nxt=='%' { i+=2; continue; }
            else if nxt=='s' { placeholders.push(Placeholder::S(col)); i+=2; }
            else if nxt=='q' { placeholders.push(Placeholder::Q(col)); i+=2; }
            else if nxt=='*' {
                if i+2>=chars.len() { return Err("error: xplr -m: template ended with incomplete placeholder\n".to_string()); }
                let nxt2=chars[i+2];
                if nxt2=='s' { placeholders.push(Placeholder::StarS(col)); i+=3; }
                else if nxt2=='q' { placeholders.push(Placeholder::StarQ(col)); i+=3; }
                else { return Err(format!("error: xplr -m: invalid placeholder '%*{}' at column {}, use one of '%s' or '%q', or escape it using '%%'\n", nxt2, col)); }
            } else { return Err(format!("error: xplr -m: invalid placeholder '%{}' at column {}, use one of '%s' or '%q', or escape it using '%%'\n", nxt, col)); }
        } else { i+=1; }
    }
    Ok(placeholders)
}

fn substitute_template(template: &str, placeholders: &[Placeholder], values: &[String]) -> Result<String, String> {
    let mut result=String::new();
    let chars: Vec<char>=template.chars().collect();
    let mut i=0;
    let mut val_idx=0;
    let mut ph_idx=0;
    while i<chars.len() {
        if chars[i]=='%' {
            if i+1<chars.len() && chars[i+1]=='%' { result.push('%'); i+=2; continue; }
            if ph_idx>=placeholders.len() { result.push(chars[i]); i+=1; continue; }
            let ph=&placeholders[ph_idx];
            ph_idx+=1;
            match ph {
                Placeholder::S(col) => {
                    if val_idx>=values.len() { return Err(format!("error: xplr -m: placeholder missing value at column {}\n", col)); }
                    result.push_str(&values[val_idx]); val_idx+=1; i+=2;
                },
                Placeholder::Q(col) => {
                    if val_idx>=values.len() { return Err(format!("error: xplr -m: placeholder missing value at column {}\n", col)); }
                    let v=&values[val_idx];
                    let quoted=serde_json::to_string(v).unwrap();
                    result.push_str(&quoted); val_idx+=1; i+=2;
                },
                Placeholder::StarS(_col) => {
                    let remaining=&values[val_idx..];
                    let joined=remaining.join(",");
                    result.push_str(&joined);
                    val_idx=values.len(); i+=3;
                    if ph_idx < placeholders.len() {
                        let next_col = match placeholders[ph_idx] { Placeholder::S(c)|Placeholder::Q(c)|Placeholder::StarS(c)|Placeholder::StarQ(c)=>c };
                        return Err(format!("error: xplr -m: placeholder missing value at column {}\n", next_col));
                    }
                    break;
                },
                Placeholder::StarQ(_col) => {
                    let remaining=&values[val_idx..];
                    let quoted_vals: Vec<String>=remaining.iter().map(|v| serde_json::to_string(v).unwrap()).collect();
                    let joined=quoted_vals.join(",");
                    result.push_str(&joined);
                    val_idx=values.len(); i+=3;
                    if ph_idx < placeholders.len() {
                        let next_col = match placeholders[ph_idx] { Placeholder::S(c)|Placeholder::Q(c)|Placeholder::StarS(c)|Placeholder::StarQ(c)=>c };
                        return Err(format!("error: xplr -m: placeholder missing value at column {}\n", next_col));
                    }
                    break;
                },
            }
        } else { result.push(chars[i]); i+=1; }
    }
    if val_idx < values.len() { return Err("error: xplr -m: too many positional values, not enough positional placeholders\n".to_string()); }
    Ok(result)
}

