    Search(String), SearchFromInput, SearchFuzzy(String), SearchFuzzyFromInput, SearchFuzzyUnordered(String), SearchFuzzyUnorderedFromInput, SearchRegex(String), SearchRegexFromInput, SearchRegexUnordered(String), SearchRegexUnorderedFromInput, ToggleSearchAlgorithm, EnableSearchOrder, DisableSearchOrder, ToggleSearchOrder, AcceptSearch, CancelSearch,
    EnableMouse, DisableMouse, ToggleMouse, StartFifo(String), StopFifo, ToggleFifo(String),
    LogInfo(String), LogSuccess(String), LogWarning(String), LogError(String), Debug(String),
    Quit, PrintPwdAndQuit, PrintFocusPathAndQuit, PrintSelectionAndQuit, PrintResultAndQuit, PrintAppStateAndQuit, Terminate,
}

fn validate_message_m(yaml_str: &str) -> Result<serde_json::Value, String> {
    let yaml_val: serde_yaml::Value = match serde_yaml::from_str(yaml_str) {
        Ok(v) => v,
        Err(e) => return Err(format!("error: xplr -m: yaml: {}\n", e)),
    };
    let json_inter = serde_json::to_value(&yaml_val).unwrap();
    let de: Result<MsgEnum, _> = serde_json::from_value(json_inter.clone());
    match de {
        Ok(msg) => Ok(serde_json::to_value(&msg).unwrap()),
        Err(e) => {
            let s = e.to_string();
            if s.contains("at line") { return Err(format!("error: {}\n", s)); }
            if s.contains("unknown variant") {
                let key = yaml_str.split(':').next().unwrap_or("").trim();
                let col = key.len() + 3;
                let ns = format!("{} at line 1 column {}", s, col);
                return Err(format!("error: {}\n", ns));
            }
            let value_part = yaml_str.splitn(2, ':').nth(1).unwrap_or("").trim();
            let is_quoted = value_part.starts_with('"') || value_part.starts_with('\'');
            let is_bool = value_part=="true"||value_part=="false"||value_part=="null"||value_part=="~";
            let is_numeric = value_part.parse::<i64>().is_ok() || value_part.parse::<f64>().is_ok();
            let col = if !is_quoted && !is_bool && !is_numeric && !value_part.is_empty() { yaml_str.len()+4 } else { yaml_str.len()+2 };
            let ns = format!("{} at line 1 column {}", s, col);
            return Err(format!("error: {}\n", ns));
        }
    }
}

fn validate_on_load(yaml_str: &str) -> Result<(), String> {
    // For on-load, we use more permissive check: try serde_yaml::from_str as Value first, then check unknown variant via MsgEnum json, but allow scalar types for String
    let yaml_val: serde_yaml::Value = match serde_yaml::from_str(yaml_str) {
        Ok(v) => v,
        Err(e) => return Err(format!("error: {}\n", e)),
    };
    // Check unknown variant by trying to deserialize via json
    let json_inter = serde_json::to_value(&yaml_val).unwrap();
    let de: Result<MsgEnum, _> = serde_json::from_value(json_inter);
    match de {
        Ok(_) => Ok(()),
        Err(e) => {
            let s = e.to_string();
            // For on-load, if error is invalid type for String fields (like LogSuccess: true), we treat as ok (No device)
            // So only propagate unknown variant and map vs unit errors, etc.
            if s.contains("unknown variant") {
                return Err(format!("error: {}\n", s));
            }
            // For invalid type where expected String but got boolean/integer/null, allow
            if s.contains("expected a string") && (yaml_val.is_string() || matches!(yaml_val, serde_yaml::Value::Bool(_)|serde_yaml::Value::Number(_)|serde_yaml::Value::Null)) {
                // Check if yaml is mapping with String value? Actually LogSuccess: true => yaml_val is Mapping {"LogSuccess": Bool(true)}
                // For such, the error is "invalid type: boolean `true`, expected a string"
                // We want to allow this for on-load (treat as success)
                // So check if the error is about string but yaml value for that key is scalar bool/int/null
                // For now, allow any string-expected errors where value is scalar
                if s.contains("expected a string") {
                    return Ok(());
                }
            }
            // For unit variant errors like "invalid type: map, expected unit variant" keep as error
            if s.contains("expected unit variant") || s.contains("invalid type: map") {
                // Need to return without column? Original for on-load unit errors has no column
                return Err(format!("error: {}\n", s));
            }
            // For other invalid types (like usize), keep with prefix?
            // For on-load, invalid type for usize includes prefix like "FocusNextByRelativeIndex: invalid type..."
            // That is different from -M. For on-load, we need to prefix with key.
            // The error s is "invalid type: string \"2\", expected usize"
            // Original on-load error is "FocusNextByRelativeIndex: invalid type: string \"2\", expected usize at line 1 column 27"
            // So we need to prefix key and add column 27 (which is key_len+3)
            if s.contains("expected usize") || s.contains("expected struct") || s.contains("expected a string") {
                // Determine key
                let key = yaml_str.split(':').next().unwrap_or("").trim();
                // For on-load, column is key_len+3? Let's check: "FocusNextByRelativeIndex: \"2\"" key len 24 => col 27 => key_len+3 =27 yes
                // For "FocusNextByRelativeIndex: notanint" key 24 => col 27 as well (not 38). So for on-load, column is always key_len+3, not len+?
                let col = key.len() + 3;
                let ns = format!("{}: {} at line 1 column {}", key, s, col);
                return Err(format!("error: {}\n", ns));
            }
            // Otherwise, return original with column?
            // For generic, just return without column as original does for on-load unknown?
            return Err(format!("error: {}\n", s));
        }
    }
}

fn main() {
    let args: Vec<String> = env::args().collect();
    let mut help_seen=false; let mut version_seen=false;
    let mut help_pos=usize::MAX; let mut version_pos=usize::MAX;
    let mut dash=false; let mut double_dash=false;
    let mut read0=false; let mut _write0=false;
    let mut vroot: Option<String>=None;
    let mut positional: Vec<String>=Vec::new();
    let mut i=1;
    while i<args.len() {
        let arg=args[i].clone();
        if double_dash { positional.push(arg); i+=1; continue; }
        match arg.as_str() {
            "--" => { double_dash=true; i+=1; },
            "-" => { dash=true; i+=1; },
            "-h"|"--help" => { help_seen=true; help_pos=i; i+=1; },
            "-V"|"--version" => { version_seen=true; version_pos=i; i+=1; },
            "--force-focus"|"--print-pwd-as-result"|"--read-only" => { i+=1; },
            "--read0" => { read0=true; i+=1; },
            "--write0" => { _write0=true; i+=1; },
            "-0"|"--null" => { read0=true; _write0=true; i+=1; },
            "-c"|"--config" => {
                if i+1>=args.len() { eprintln!("error: usage: xplr -c PATH"); process::exit(1); }
                let val=args[i+1].clone();
                let exists = if Path::new(&val).is_absolute() { Path::new(&val).exists() } else { env::current_dir().unwrap_or(PathBuf::from(".")).join(&val).exists() };
                if !exists {
                    let disp = if Path::new(&val).is_absolute() { val.clone() } else { env::current_dir().unwrap().join(&val).to_string_lossy().to_string() };
                    eprintln!("error: path doesn't exist: {}", disp); process::exit(1);
                }
                i+=2;
            },
            "-C"|"--extra-config" => {
                i+=1;
                while i<args.len() {
                    let nxt=args[i].clone();
                    if nxt=="--"||nxt=="-"||nxt.starts_with('-') { break; }
                    let exists = if Path::new(&nxt).is_absolute() { Path::new(&nxt).exists() } else { env::current_dir().unwrap().join(&nxt).exists() };
                    if !exists {
                        let disp = if Path::new(&nxt).is_absolute() { nxt.clone() } else { env::current_dir().unwrap().join(&nxt).to_string_lossy().to_string() };
                        eprintln!("error: path doesn't exist: {}", disp); process::exit(1);
                    }
                    i+=1;
                }
            },
            "--on-load" => {
                i+=1;
                while i<args.len() {
                    let nxt=args[i].clone();
                    if nxt=="--"||nxt=="-"||nxt.starts_with('-') { break; }
                    let help_before = help_seen && help_pos < i;
                    let version_before = version_seen && version_pos < i;
                    if help_before || version_before {
                        // suppress validation
                        i+=1; continue;
                    }
                    if let Err(e) = validate_on_load(&nxt) {
                        eprint!("{}", e); process::exit(1);
                    }
                    i+=1;
                }
            },
            "--vroot" => {
                if i+1>=args.len() { eprintln!("error: usage: xplr --vroot PATH"); process::exit(1); }
                let val=args[i+1].clone();
                let exists = if Path::new(&val).is_absolute() { Path::new(&val).exists() } else { env::current_dir().unwrap().join(&val).exists() };
                if !exists {
                    let disp = if Path::new(&val).is_absolute() { val.clone() } else { env::current_dir().unwrap().join(&val).to_string_lossy().to_string() };
                    eprintln!("error: path doesn't exist: {}", disp); process::exit(1);
                }
                vroot=Some(val); i+=2;
            },
            "-m"|"--pipe-msg-in"|"-M"|"--print-msg-in" => {
                let is_print = arg=="-M"||arg=="--print-msg-in";
                if i+1>=args.len() { eprintln!("error: xplr -m: placeholder missing value at column 1"); process::exit(1); }
                let tmpl=args[i+1].clone();
                i+=2;
                let help_before = help_seen && help_pos < i-2;
                let version_before = version_seen && version_pos < i-2;
                if help_before || version_before { i=args.len(); continue; }
                let placeholders = match parse_template(&tmpl) {
                    Ok(p)=>p,
                    Err(e)=>{ eprint!("{}", e); process::exit(1); }
                };
                let mut values: Vec<String>=Vec::new();
                let mut idx=0;
                let remaining=&args[i..];
                let mut err=None;
                for (pi, ph) in placeholders.iter().enumerate() {
                    match ph {
                        Placeholder::S(col)|Placeholder::Q(col) => {
                            if idx>=remaining.len() { err=Some(format!("error: xplr -m: placeholder missing value at column {}\n", col)); break; }
                            values.push(remaining[idx].clone()); idx+=1;
                        },
                        Placeholder::StarS(_col)|Placeholder::StarQ(_col) => {
                            for r in &remaining[idx..] { values.push(r.clone()); }
                            idx=remaining.len();
                            if pi+1 < placeholders.len() {
                                let nc = match placeholders[pi+1] { Placeholder::S(c)|Placeholder::Q(c)|Placeholder::StarS(c)|Placeholder::StarQ(c)=>c };
                                err=Some(format!("error: xplr -m: placeholder missing value at column {}\n", nc)); break;
                            }
                            break;
                        },
                    }
                }
                if let Some(e)=err { eprint!("{}", e); process::exit(1); }
                if idx < remaining.len() { eprint!("error: xplr -m: too many positional values, not enough positional placeholders\n"); process::exit(1); }
                let substituted = match substitute_template(&tmpl, &placeholders, &values) {
                    Ok(s)=>s, Err(e)=>{ eprint!("{}", e); process::exit(1); }
                };
                let json_val = match validate_message_m(&substituted) {
                    Ok(v)=>v, Err(e)=>{ eprint!("{}", e); process::exit(1); }
                };
                let json_str=serde_json::to_string(&json_val).unwrap();
                if is_print {
                    print!("{}", json_str); process::exit(0);
                } else {
                    let pipe = env::var("XPLR_PIPE_MSG_IN").ok();
                    if let Some(pipe_path)=pipe {
                        if !Path::new(&pipe_path).exists() { eprintln!("error: No such file or directory (os error 2)"); process::exit(1); }
                        let content=fs::read(&pipe_path).unwrap_or(Vec::new());
                        if content.is_empty() { eprintln!("error: failed to detect delimmiter"); process::exit(1); }
                        let has_null=content.contains(&0);
                        let has_nl=content.contains(&b'\n');
                        let delim = if has_null { "\0" } else if has_nl { "\n" } else { eprintln!("error: failed to detect delimmiter"); process::exit(1); };
                        use std::fs::OpenOptions; use std::io::Write;
                        let mut f=OpenOptions::new().append(true).open(&pipe_path).unwrap();
                        f.write_all(json_str.as_bytes()).unwrap();
                        f.write_all(delim.as_bytes()).unwrap();
                        process::exit(0);
                    } else {
                        println!("{}", json_str); process::exit(0);
                    }
                }
            },
            _ => {
                if arg.starts_with('-') { eprintln!("error: invalid argument: \"{}\", try `-- \"{}\"` or `--help`", arg, arg); process::exit(1); }
                else { positional.push(arg); i+=1; }
            }
        }
    }

    // stdin dash
    let mut stdin_paths: Vec<String>=Vec::new();
    if dash {
        let delim = if read0 { b'\0' } else { b'\n' };
        let mut buf=Vec::new(); io::stdin().read_to_end(&mut buf).unwrap();
        let mut start=0;
        for idx in 0..buf.len() {
            if buf[idx]==delim {
                let slice=&buf[start..idx];
                let s=String::from_utf8_lossy(slice).to_string();
                if s.is_empty() { eprintln!("error: empty string passed"); process::exit(1); }
                let exists = if Path::new(&s).is_absolute() { Path::new(&s).exists() } else { env::current_dir().unwrap().join(&s).exists() };
                if !exists {
                    let disp = if Path::new(&s).is_absolute() { s.clone() } else { env::current_dir().unwrap().join(&s).to_string_lossy().to_string() };
                    eprintln!("error: path doesn't exist: {}", disp); process::exit(1);
                }
                if let Some(ref vr)=vroot { if !is_inside_vroot(&s, vr) { eprintln!("error: \"{}\" is outside of virtual root \"{}\"", s, vr); process::exit(1); } }
                stdin_paths.push(s); start=idx+1;
            }
        }
        if start < buf.len() {
            let slice=&buf[start..];
            let s=String::from_utf8_lossy(slice).to_string();
            if !s.is_empty() {
                let exists = if Path::new(&s).is_absolute() { Path::new(&s).exists() } else { env::current_dir().unwrap().join(&s).exists() };
                if !exists {
                    let disp = if Path::new(&s).is_absolute() { s.clone() } else { env::current_dir().unwrap().join(&s).to_string_lossy().to_string() };
                    eprintln!("error: path doesn't exist: {}", disp); process::exit(1);
                }
                if let Some(ref vr)=vroot { if !is_inside_vroot(&s, vr) { eprintln!("error: \"{}\" is outside of virtual root \"{}\"", s, vr); process::exit(1); } }
                stdin_paths.push(s);
            }
        } else if buf.is_empty() {
        } else if buf.len()>0 && buf[buf.len()-1]==delim {
        }
        if positional.is_empty() { positional=stdin_paths; }
    }

    if !positional.is_empty() {
        let p=&positional[0];
        if p.is_empty() { eprintln!("error: empty string passed"); process::exit(1); }
        let exists = if Path::new(p).is_absolute() { Path::new(p).exists() } else { env::current_dir().unwrap().join(p).exists() };
        if !exists {
            let disp = if Path::new(p).is_absolute() { p.clone() } else { env::current_dir().unwrap().join(p).to_string_lossy().to_string() };
            eprintln!("error: path doesn't exist: {}", disp); process::exit(1);
        }
        if let Some(ref vr)=vroot { if !is_inside_vroot(p, vr) { eprintln!("error: \"{}\" is outside of virtual root \"{}\"", p, vr); process::exit(1); } }
        for sel in &positional[1..] {
            if sel.is_empty() { eprintln!("error: empty string passed"); process::exit(1); }
            let exists2 = if Path::new(sel).is_absolute() { Path::new(sel).exists() } else { env::current_dir().unwrap().join(sel).exists() };
            if !exists2 {
                let disp = if Path::new(sel).is_absolute() { sel.clone() } else { env::current_dir().unwrap().join(sel).to_string_lossy().to_string() };
                eprintln!("error: path doesn't exist: {}", disp); process::exit(1);
            }
            if let Some(ref vr)=vroot { if !is_inside_vroot(sel, vr) { eprintln!("error: \"{}\" is outside of virtual root \"{}\"", sel, vr); process::exit(1); } }
        }
    } else {
        if let Some(ref vr)=vroot {
            let cwd=env::current_dir().unwrap().to_string_lossy().to_string();
            if !is_inside_vroot(&cwd, vr) { eprintln!("error: \"{}\" is outside of virtual root \"{}\"", cwd, vr); process::exit(1); }
        }
    }

    if help_seen { print!("{}", HELP_TEXT); process::exit(0); }
    if version_seen { print!("{}", VERSION_TEXT); process::exit(0); }

    eprintln!("error: No such device or address (os error 6)");
    process::exit(1);
}
